    private HttpEngine getOrCreateNtkQuicEngine(String baseUrl) {
        if(context == null || !NtkQuicFetcher.isAvailable() || baseUrl == null || baseUrl.length() == 0)
            return null;
        try {
            String host = URI.create(baseUrl).getHost();
            if(host == null || host.length() == 0)
                return null;
            FutureTask<HttpEngine> task;
            boolean owner = false;
            synchronized (ntkQuicEngineLock) {
                HttpEngine cached = ntkQuicEngines.get(host);
                if(cached != null)
                    return cached;
                task = ntkQuicEngineTasks.get(host);
                if(task == null) {
                    String engineHost = host;
                    task = new FutureTask<>(() -> buildNtkQuicEngine(engineHost));
                    ntkQuicEngineTasks.put(host, task);
                    owner = true;
                }
            }
            if(owner)
                task.run();
            HttpEngine created = task.get();
            synchronized (ntkQuicEngineLock) {
                HttpEngine cached = ntkQuicEngines.get(host);
                if(cached != null)
                    return cached;
                if(created != null)
                    ntkQuicEngines.put(host, created);
                ntkQuicEngineTasks.remove(host);
                return created;
            }
        } catch (Exception e) {
            try {
                String host = URI.create(baseUrl).getHost();
                if(host != null && host.length() > 0) {
                    synchronized (ntkQuicEngineLock) {
                        ntkQuicEngineTasks.remove(host);
                    }
                }
            } catch (Exception ignored) {
            }
            return null;
        }
    }

    private static boolean isNtkImageOriginHost(String host) {
        return isNtkWebtoonImageOriginHost(host) || isNtkManhwaImageOriginHost(host);
    }

    @TargetApi(34)
    private HttpEngine buildNtkQuicEngine(String host) {
        return new HttpEngine.Builder(context.getApplicationContext())
                .setEnableHttp2(true)
                .setEnableQuic(true)
                .setEnableBrotli(true)
                .setUserAgent(agent)
                .setQuicOptions(new QuicOptions.Builder()
                        .addAllowedQuicHost(host)
                        .setHandshakeUserAgent(agent)
                        .build())
                .addQuicHint(host, 443, 443)
                .build();
    }

    private HttpEngine getCachedNtkQuicEngine(String baseUrl) {
        if(baseUrl == null || baseUrl.length() == 0)
            return null;
        try {
            String host = URI.create(baseUrl).getHost();
            if(host == null || host.length() == 0)
                return null;
            synchronized (ntkQuicEngineLock) {
                return ntkQuicEngines.get(host);
            }
        } catch (Exception e) {
            return null;
        }
    }

    private FutureTask<HttpEngine> startNtkQuicEngineCreate(String baseUrl, String path) {
        FutureTask<HttpEngine> task = new FutureTask<>(() -> getOrCreateNtkQuicEngine(baseUrl));
        Thread thread = new Thread(task, "ntk-quic-engine-create");
        thread.setDaemon(true);
        thread.start();
        Log.d(TAG, "ntk_native_ack_engine_async_start path=" + path);
        return task;
    }

    private HttpEngine awaitNtkQuicEngine(FutureTask<HttpEngine> task, long timeoutMs, String path) {
        if(task == null)
            return null;
        try {
            HttpEngine engine = task.get(Math.max(1L, timeoutMs), TimeUnit.MILLISECONDS);
            Log.d(TAG, "ntk_native_ack_engine_async_done path=" + path
                    + ",ready=" + (engine != null));
            return engine;
        } catch(TimeoutException e) {
            Log.d(TAG, "ntk_native_ack_engine_async_timeout path=" + path);
            return null;
        } catch(InterruptedException e) {
            Thread.currentThread().interrupt();
            Log.d(TAG, "ntk_native_ack_engine_async_cancelled path=" + path);
            return null;
        } catch(Exception e) {
            Log.d(TAG, "ntk_native_ack_engine_async_error path=" + path + "," + e);
            return null;
        }
    }

    private boolean isNtkWasmWarm(String baseUrl) {
        String host = ntkHost(baseUrl);
        if(host.length() == 0)
            return false;
        synchronized (ntkQuicEngineLock) {
            Long warmedAt = ntkWasmWarmCache.get(host);
            if(warmedAt == null)
                return false;
            if(System.currentTimeMillis() - warmedAt >= NTK_WASM_WARM_CACHE_TTL_MS) {
                ntkWasmWarmCache.remove(host);
                return false;
            }
            return true;
        }
    }

    private void markNtkWasmWarm(String baseUrl) {
        String host = ntkHost(baseUrl);
        if(host.length() == 0)
            return;
        synchronized (ntkQuicEngineLock) {
            ntkWasmWarmCache.put(host, System.currentTimeMillis());
        }
    }

    private String ntkHost(String baseUrl) {
        if(baseUrl == null || baseUrl.length() == 0)
            return "";
        try {
            String host = URI.create(baseUrl).getHost();
            return host == null ? "" : host;
        } catch (Exception e) {
            return "";
        }
    }

    private ExecutorService getOrCreateNtkQuicExecutor(String baseUrl) {
        if(baseUrl == null || baseUrl.length() == 0)
            return null;
        try {
            String host = URI.create(baseUrl).getHost();
            if(host == null || host.length() == 0)
                return null;
            synchronized (ntkQuicEngineLock) {
                ExecutorService cached = ntkQuicExecutors.get(host);
                if(cached != null && !cached.isShutdown())
                    return cached;
                ExecutorService created = Executors.newFixedThreadPool(NTK_QUIC_CALLBACK_THREADS_PER_HOST);
                ntkQuicExecutors.put(host, created);
                return created;
            }
        } catch (Exception e) {
            return null;
        }
    }

    @TargetApi(34)
    private void dropNtkQuicEngine(String baseUrl) {
        if(baseUrl == null || baseUrl.length() == 0)
            return;
        try {
            String host = URI.create(baseUrl).getHost();
            if(host == null || host.length() == 0)
                return;
            HttpEngine engine;
            ExecutorService executor;
            synchronized (ntkQuicEngineLock) {
                engine = ntkQuicEngines.remove(host);
                ntkQuicEngineTasks.remove(host);
                executor = ntkQuicExecutors.remove(host);
                ntkWasmWarmCache.remove(host);
            }
            if(engine != null)
                engine.shutdown();
            shutdownNtkQuicExecutor(executor);
        } catch (Exception ignored) {
        }
    }

    @TargetApi(34)
    private void shutdownNtkQuicEngines() {
        List<HttpEngine> engines;
        List<ExecutorService> executors;
        synchronized (ntkQuicEngineLock) {
            engines = new ArrayList<>(ntkQuicEngines.values());
            executors = new ArrayList<>(ntkQuicExecutors.values());
            ntkQuicEngines.clear();
            ntkQuicEngineTasks.clear();
            ntkQuicExecutors.clear();
            ntkWasmWarmCache.clear();
        }
        for(HttpEngine engine : engines) {
            try {
                engine.shutdown();
            } catch (Exception ignored) {
            }
        }
        for(ExecutorService executor : executors)
            shutdownNtkQuicExecutor(executor);
    }

    private void shutdownNtkQuicExecutor(ExecutorService executor) {
        if(executor == null)
            return;
        try {
            executor.shutdown();
            executor.awaitTermination(2_500L, TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } catch (Exception ignored) {
        }
    }

    private NtkQuicFetcher.Result fetchNtkQuic(String baseUrl, String url, String cookieHeader,
                                               Map<String, String> headers, String method, byte[] body,
                                               long timeoutMs) throws InterruptedException {
        return fetchNtkQuic(baseUrl, url, cookieHeader, headers, method, body, timeoutMs, null);
    }

    private NtkQuicFetcher.Result fetchNtkQuic(String baseUrl, String url, String cookieHeader,
                                               Map<String, String> headers, String method, byte[] body,
                                               long timeoutMs,
                                               NtkQuicFetcher.PartialTextObserver partialTextObserver) throws InterruptedException {
        return fetchNtkQuic(baseUrl, url, cookieHeader, headers, method, body, timeoutMs,
                partialTextObserver, null);
    }

    private NtkQuicFetcher.Result fetchNtkQuic(String baseUrl, String url, String cookieHeader,
                                               Map<String, String> headers, String method, byte[] body,
                                               long timeoutMs,
                                               NtkQuicFetcher.PartialTextObserver partialTextObserver,
                                               NtkQuicFetcher.PartialBytesObserver partialBytesObserver) throws InterruptedException {
        HttpEngine engine = getOrCreateNtkQuicEngine(baseUrl);
        if(engine == null)
            return NtkQuicFetcher.fetch(context, url, agent, cookieHeader, headers, method, body, timeoutMs,
                    partialTextObserver);
        ExecutorService executor = getOrCreateNtkQuicExecutor(baseUrl);
        try {
            if(executor != null)
                return NtkQuicFetcher.fetchWithEngine(engine, executor, url, agent, cookieHeader, headers, method, body, timeoutMs,
                        partialTextObserver, partialBytesObserver);
            return NtkQuicFetcher.fetchWithEngine(engine, url, agent, cookieHeader, headers, method, body, timeoutMs,
                    partialTextObserver);
        } catch (IllegalStateException e) {
            dropNtkQuicEngine(baseUrl);
            return NtkQuicFetcher.fetch(context, url, agent, cookieHeader, headers, method, body, timeoutMs,
                    partialTextObserver);
        }
    }

    private static boolean shouldSkipEarlyNtkRscAckPreflight(String baseUrl, String path) {
        if(path == null)
            return false;
        // Numeric NTK episodes have a complete native manifest/API route. Starting Chromium here
        // races that route and can stall the UI thread before the reader is opened.
        if(isNumericNtkGeneratedEpisodePath(path))
            return true;
        if(!isModernNtkGuardRoot(baseUrl))
            return false;
        if(path.matches("^/webtoon/\\d{1,12}/kp-[^/?#]+(?:[/?#].*)?$"))
            return true;
        boolean generatedPath = path.matches("^/(?:webtoon|manhwa)/\\d+/\\d+(?:[/?#].*)?$")
                || isNtkSyntheticWebtoonEpisodePath(path);
        if(!generatedPath)
            return false;
        if(!ReaderImageCache.INSTANCE.earlyNtkGeneratedSuccessImageUrls(
                path, SystemClock.elapsedRealtime() - 30000L).isEmpty())
            return true;
        return MainApplication.isNtkForegroundViewerPath(path)
                && ReaderImageCache.INSTANCE.speculativeNtkGeneratedImageUrls(
                path, SystemClock.elapsedRealtime() - 30000L).size() >= 2;
    }

    static boolean shouldSkipEarlyNtkRscAckPreflightForTest(String baseUrl, String path) {
        return shouldSkipEarlyNtkRscAckPreflight(baseUrl, path);
    }

    private static boolean isInitialNtkWebtoonAckHoldPath(String path) {
        return isNtkModernViewerPath(path);
    }

    private static boolean isNtkModernViewerKind(String kind) {
        return "webtoon".equals(kind) || "manhwa".equals(kind);
    }

    private static boolean isNtkModernViewerPath(String path) {
        return path != null && (path.startsWith("/webtoon/") || path.startsWith("/manhwa/"));
    }

    private NtkQuicFetcher.Result fetchNtkQuicUntilText(String baseUrl, String url,
                                                       String cookieHeader,
                                                       Map<String, String> headers,
                                                       String method, byte[] body,
                                                       long timeoutMs,
                                                       NtkQuicFetcher.EarlyTextObserver earlyTextObserver)
            throws InterruptedException {
        HttpEngine engine = getOrCreateNtkQuicEngine(baseUrl);
        if(engine == null)
            return NtkQuicFetcher.fetch(context, url, agent, cookieHeader, headers, method, body, timeoutMs,
                    text -> {
                        if(earlyTextObserver == null)
                            return;
                        earlyTextObserver.onPartialText(0, Collections.emptyMap(), text);
                    });
        ExecutorService executor = getOrCreateNtkQuicExecutor(baseUrl);
        try {
            if(executor != null)
                return NtkQuicFetcher.fetchWithEngineUntilText(engine, executor, url, agent,
                        cookieHeader, headers, method, body, timeoutMs, earlyTextObserver);
            return NtkQuicFetcher.fetchWithEngine(engine, url, agent, cookieHeader, headers,
                    method, body, timeoutMs, text -> {
                        if(earlyTextObserver == null)
                            return;
                        earlyTextObserver.onPartialText(0, Collections.emptyMap(), text);
                    });
        } catch (IllegalStateException e) {
            dropNtkQuicEngine(baseUrl);
            return NtkQuicFetcher.fetch(context, url, agent, cookieHeader, headers, method, body, timeoutMs,
                    text -> {
                        if(earlyTextObserver == null)
                            return;
                        earlyTextObserver.onPartialText(0, Collections.emptyMap(), text);
                    });
        }
    }

    public boolean isNtkImageHeaderReachable(String url, Map<String, String> headers, long timeoutMs) {
        return ntkImageHeaderReachability(url, headers, timeoutMs) > 0;
    }

    public int ntkImageHeaderReachability(String url, Map<String, String> headers, long timeoutMs) {
        return ntkImageHeaderReachability(url, headers, timeoutMs, null);
    }

    public int ntkImageHeaderReachability(String url, Map<String, String> headers, long timeoutMs,
                                          String strictEpisodePath) {
        long speculationEpoch = captureNtkStrictLegacySpeculationEpoch();
        if(shouldSkipOwnedDirectWifiStrictLegacyImageProbe(strictEpisodePath))
            return NTK_IMAGE_HEADER_REACHABILITY_SUPERSEDED;
        if(isNtkGeneratedImageCdnUrl(url)) {
            int okhttpReachable = ntkImageHeaderReachabilityOkHttp(url, headers);
            if(!canPublishNtkStrictLegacySpeculation(speculationEpoch, strictEpisodePath))
                return NTK_IMAGE_HEADER_REACHABILITY_SUPERSEDED;
            if(okhttpReachable >= 0)
                return okhttpReachable;
        }
        // The strict owner may have published while the bounded OkHttp header probe was active.
        // Recheck before a failed legacy probe is allowed to fan out into QUIC.
        if(shouldSkipOwnedDirectWifiStrictLegacyImageProbe(strictEpisodePath))
            return NTK_IMAGE_HEADER_REACHABILITY_SUPERSEDED;
        if(context == null || url == null || url.length() == 0
                || !NtkQuicFetcher.isAvailable() || !shouldUseNtkQuicPrimaryUrl(url))
            return -1;
        HttpUrl parsed = HttpUrl.parse(url);
        if(parsed == null)
            return -1;
        String baseUrl = rootFromHttpUrl(parsed);
        Map<String, String> requestHeaders = headers == null
                ? new LinkedHashMap<>() : new LinkedHashMap<>(headers);
        if(headerValue(requestHeaders, "Cookie") == null)
            requestHeaders.put("Cookie", getCookieHeader());
        if(headerValue(requestHeaders, "User-Agent") == null)
            requestHeaders.put("User-Agent", agent);
        String cookieHeader = headerValue(requestHeaders, "Cookie");
        final boolean[] reachable = new boolean[]{false};
        long startedAt = System.currentTimeMillis();
        HttpEngine engine = getOrCreateNtkQuicEngine(baseUrl);
        if(engine == null)
            return -1;
        ExecutorService executor = getOrCreateNtkQuicExecutor(baseUrl);
        try {
            if(executor == null)
                return -1;
            NtkQuicFetcher.Result result = NtkQuicFetcher.fetchWithEngineUntilResponseStarted(
                    engine, executor, url, agent, cookieHeader, requestHeaders, "GET", null,
                    Math.max(1L, timeoutMs), (code, responseHeaders) -> {
                        String contentType = contentTypeHeader(responseHeaders);
                        reachable[0] = (code >= 200 && code < 300 || code == 206)
                                && contentType.toLowerCase(Locale.ROOT).startsWith("image/");
                        return true;
                    });
            Log.d(TAG, "ntk_image_header_probe code=" + (result == null ? 0 : result.code)
                    + ",reachable=" + reachable[0]
                    + ",error=" + (result == null ? null : result.error)
                    + ",ms=" + (System.currentTimeMillis() - startedAt)
                    + ",url=" + safeLogUrl(url));
            if(result == null || result.error != null)
                return -1;
            if(!canPublishNtkStrictLegacySpeculation(speculationEpoch, strictEpisodePath))
                return NTK_IMAGE_HEADER_REACHABILITY_SUPERSEDED;
            return reachable[0] ? 1 : 0;
        } catch(Exception e) {
            Log.d(TAG, "ntk_image_header_probe_error error=" + e.getClass().getSimpleName()
                    + ",ms=" + (System.currentTimeMillis() - startedAt)
                    + ",url=" + safeLogUrl(url));
            return -1;
        }
    }

    private int ntkImageHeaderReachabilityOkHttp(String url, Map<String, String> headers) {
        Response response = null;
        long startedAt = System.currentTimeMillis();
        try {
            Map<String, String> requestHeaders = headers == null
                    ? new LinkedHashMap<>() : new LinkedHashMap<>(headers);
            requestHeaders.put("Range", "bytes=0-31");
            if(headerValue(requestHeaders, "Accept-Encoding") == null)
                requestHeaders.put("Accept-Encoding", "identity");
            response = get(url, requestHeaders);
            int code = response == null ? 0 : response.code();
            String contentType = response == null || response.body() == null
                    ? "" : String.valueOf(response.body().contentType()).toLowerCase(Locale.ROOT);
            byte[] bytes = response == null || response.body() == null
                    ? new byte[0] : response.body().bytes();
            boolean reachable = (code >= 200 && code < 300 || code == 206)
                    && contentType.startsWith("image/")
                    && looksLikeNtkImageHeader(bytes);
            Log.d(TAG, "ntk_image_header_probe_okhttp code=" + code
                    + ",reachable=" + reachable
                    + ",bytes=" + bytes.length
                    + ",ms=" + (System.currentTimeMillis() - startedAt)
                    + ",url=" + safeLogUrl(url));
            if(reachable)
                return 1;
            if(code >= 200 && code < 300 || code == 206)
                return 0;
            if(code == 403 && shouldUseNtkQuicPrimaryUrl(url)) {
                Log.d(TAG, "ntk_image_header_probe_okhttp_403_try_quic url=" + safeLogUrl(url));
                return -1;
            }
            return code == 404 || code == 403 || code == 410 ? 0 : -1;
        } catch(Exception e) {
            Log.d(TAG, "ntk_image_header_probe_okhttp_error error=" + e.getClass().getSimpleName()
                    + ",ms=" + (System.currentTimeMillis() - startedAt)
                    + ",url=" + safeLogUrl(url));
            return -1;
        } finally {
            if(response != null)
                response.close();
        }
    }

    private static boolean isNtkGeneratedImageCdnUrl(String url) {
        if(url == null)
            return false;
        try {
            HttpUrl parsed = HttpUrl.parse(url);
            if(parsed == null || parsed.host() == null)
                return false;
            String host = parsed.host().toLowerCase(Locale.ROOT);
            String path = parsed.encodedPath() == null ? "" : parsed.encodedPath().toLowerCase(Locale.ROOT);
            if(isSafeNtkPageImagePath(path))
                return true;
            return host.equals("i.toonflix.app")
                    || host.endsWith(".toonflix.app")
                    || host.matches("flysky\\d*m\\.com")
                    || host.matches("apihost\\d*\\.com")
                    || "moamoabon.com".equals(host)
                    || host.matches("[a-z0-9-]+\\.worldcup\\d+\\.xyz");
        } catch(Exception ignored) {
            return false;
        }
    }

    private static boolean isNtkWorldcupImageUrl(String url) {
        if(url == null)
            return false;
        try {
            HttpUrl parsed = HttpUrl.parse(url);
            if(parsed == null || parsed.host() == null)
                return false;
            return parsed.host().toLowerCase(Locale.ROOT)
                    .matches("[a-z0-9-]+\\.worldcup\\d+\\.xyz");
        } catch(Exception ignored) {
            return false;
        }
    }

    private static boolean isFastOkHttpGeneratedImageUrl(String url) {
        if(url == null)
            return false;
        try {
            HttpUrl parsed = HttpUrl.parse(url);
            if(parsed == null || parsed.host() == null)
                return false;
            String host = parsed.host().toLowerCase(Locale.ROOT);
            return host.matches("[a-z0-9-]+\\.worldcup\\d+\\.xyz")
                    || host.matches("aws-cdn\\d*\\.site")
                    || (host.matches("booktoki\\d*\\.org")
                    && isSafeNtkPageImagePath(parsed.encodedPath() == null
                    ? "" : parsed.encodedPath().toLowerCase(Locale.ROOT)));
        } catch(Exception ignored) {
            return false;
        }
    }

    /**
     * A direct-Wi-Fi webtoon strict click globally retires generated guesses, including guesses
     * carrying a stale/wrong episode id whose path cannot yet have an authoritative manifest.
     * The manifest-owned fallback remains for the post-discovery state. Mobile/SNI and manhwa do
     * not enter the global branch.
     */
    public boolean shouldSkipDirectWifiStrictLegacySpeculation(String path) {
        boolean directWifiWebtoonOwner = isNtkWifiTransportActive()
                && !isNtkCellularResilientTransportActive()
                && ntkStrictForegroundNetworkPath != null
                && ntkStrictForegroundNetworkPath.startsWith("/webtoon/");
        if(directWifiWebtoonOwner)
            return true;
        return ReaderImageCache.shouldSkipDirectWifiStrictLegacySpeculation(
                path,
                isNtkWifiTransportActive(),
                isNtkCellularResilientTransportActive());
    }

    public long captureNtkStrictLegacySpeculationEpoch() {
        return ntkStrictLegacySpeculationCutoverEpoch.get();
    }

    /**
     * A result can publish only if no direct-Wi-Fi strict cutover occurred since its producer
     * started and no strict owner currently suppresses it. The epoch is intentionally not reset on
     * leave or transport change, preserving provenance for late callbacks forever.
     */
    public boolean canPublishNtkStrictLegacySpeculation(long producerEpoch, String path) {
        synchronized(ntkStrictForegroundNetworkLock) {
            return producerEpoch == ntkStrictLegacySpeculationCutoverEpoch.get()
                    && !shouldSkipDirectWifiStrictLegacySpeculation(path);
        }
    }

    /**
     * Commits legacy cache/publication state under the same lock used by strict cutover. The
     * cutover therefore happens wholly before this publication (which rejects) or wholly after it
     * (which immediately cancels/fences the started legacy work); check-then-write is impossible.
     */
    public boolean commitNtkStrictLegacySpeculation(long producerEpoch, String path,
                                                     Runnable publication) {
        if(publication == null)
            return false;
        synchronized(ntkStrictForegroundNetworkLock) {
            if(producerEpoch != ntkStrictLegacySpeculationCutoverEpoch.get()
                    || shouldSkipDirectWifiStrictLegacySpeculation(path))
                return false;
            publication.run();
            return true;
        }
    }

    private boolean shouldSkipOwnedDirectWifiStrictLegacyImageProbe(String path) {
        return shouldSkipDirectWifiStrictLegacySpeculation(path);
    }

    private static boolean looksLikeNtkImageHeader(byte[] bytes) {
        if(bytes == null || bytes.length < 4)
            return false;
        int b0 = bytes[0] & 0xff;
        int b1 = bytes[1] & 0xff;
        int b2 = bytes[2] & 0xff;
        int b3 = bytes[3] & 0xff;
        if(b0 == 0xff && b1 == 0xd8)
            return true;
        if(bytes.length >= 8 && b0 == 0x89 && b1 == 0x50 && b2 == 0x4e && b3 == 0x47)
            return true;
        if(b0 == 0x52 && b1 == 0x49 && b2 == 0x46 && b3 == 0x46)
            return true;
        return b0 == 0x47 && b1 == 0x49 && b2 == 0x46;
    }

    private static String contentTypeHeader(Map<String, List<String>> headers) {
        if(headers == null)
            return "";
        for(String key : headers.keySet()) {
            if(!"content-type".equalsIgnoreCase(key))
                continue;
            List<String> values = headers.get(key);
            if(values != null && !values.isEmpty() && values.get(0) != null)
                return values.get(0);
            return "";
        }
        return "";
    }

    private static boolean isLikelyPartialDecodableImage(Map<String, List<String>> headers, byte[] bytes) {
        if(bytes == null || bytes.length < 16)
            return false;
        String contentType = "";
        if(headers != null) {
            for(String key : headers.keySet()) {
                if(!"content-type".equalsIgnoreCase(key))
                    continue;
                List<String> values = headers.get(key);
                if(values != null && !values.isEmpty() && values.get(0) != null)
                    contentType = values.get(0).toLowerCase(Locale.ROOT);
                break;
            }
        }
        boolean jpeg = (bytes[0] & 0xff) == 0xff && (bytes[1] & 0xff) == 0xd8;
        boolean png = bytes.length >= 8
                && (bytes[0] & 0xff) == 0x89
                && bytes[1] == 0x50
                && bytes[2] == 0x4e
                && bytes[3] == 0x47
                && bytes[4] == 0x0d
                && bytes[5] == 0x0a
                && bytes[6] == 0x1a
                && bytes[7] == 0x0a;
        boolean webp = bytes.length >= 12
                && bytes[0] == 0x52
                && bytes[1] == 0x49
                && bytes[2] == 0x46
                && bytes[3] == 0x46
                && bytes[8] == 0x57
                && bytes[9] == 0x45
                && bytes[10] == 0x42
                && bytes[11] == 0x50;
        if(!jpeg && !png && !webp)
            return false;
        if(!(contentType.length() == 0 || contentType.contains("image/")))
            return false;
        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inJustDecodeBounds = true;
        BitmapFactory.decodeByteArray(bytes, 0, bytes.length, options);
        if(options.outWidth <= 0 || options.outHeight <= 0)
            return false;
        BitmapFactory.Options decodeOptions = new BitmapFactory.Options();
        decodeOptions.inPreferredConfig = Bitmap.Config.ARGB_8888;
        decodeOptions.inSampleSize = foregroundPartialDisplayProbeSampleSize(options.outWidth);
        Bitmap bitmap;
        try {
            bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.length, decodeOptions);
        } catch (OutOfMemoryError e) {
            return false;
        }
        if(bitmap == null)
            return false;
        bitmap.recycle();
        return true;
    }

    private static boolean shouldAcceptNtkForegroundPartialImage(int code, Map<String, List<String>> headers,
                                                                byte[] bytes) {
        if(!(code >= 200 && code < 300 || code == 206))
            return false;
        if(bytes == null || bytes.length < NTK_FOREGROUND_PARTIAL_IMAGE_BYTES)
            return false;
        return isLikelyPartialDecodableImage(headers, bytes);
    }

    private static boolean shouldMarkNtkForegroundPartialImage(NtkQuicFetcher.Result result) {
        if(!isUsableNtkQuicGetResult(result) || result.bodyBytes == null)
            return false;
        long contentLength = contentLengthHeader(result.headers);
        return contentLength <= 0L || result.bodyBytes.length < contentLength;
    }

    private static long contentLengthHeader(Map<String, List<String>> headers) {
        if(headers == null)
            return -1L;
        for(String key : headers.keySet()) {
            if(!"content-length".equalsIgnoreCase(key))
                continue;
            List<String> values = headers.get(key);
            if(values == null || values.isEmpty() || values.get(0) == null)
                return -1L;
            try {
                return Long.parseLong(values.get(0));
            } catch (NumberFormatException ignored) {
                return -1L;
            }
        }
        return -1L;
    }

    private static int foregroundPartialDisplayProbeSampleSize(int width) {
        int targetWidth = 1440;
        int maxDim = Math.max(width, targetWidth);
        int sample = 1;
        while(maxDim / (sample * 2) >= targetWidth)
            sample <<= 1;
        return sample;
    }

    private List<String> cachedNtkViewerImageUrls(String key) {
        if(key == null || key.length() == 0)
            return Collections.emptyList();
        long now = System.currentTimeMillis();
        synchronized (ntkViewerImageUrlCacheLock) {
            CachedViewerImages cached = ntkViewerImageUrlCache.get(key);
            if(cached == null)
                return Collections.emptyList();
            if(now - cached.cachedAt >= NTK_VIEWER_IMAGE_URL_CACHE_TTL_MS) {
                ntkViewerImageUrlCache.remove(key);
                return Collections.emptyList();
            }
            return new ArrayList<>(cached.urls);
        }
    }

    private List<String> recentlyCachedNtkViewerImageUrls(String key) {
        if(key == null || key.length() == 0)
            return Collections.emptyList();
        long now = System.currentTimeMillis();
        synchronized (ntkViewerImageUrlCacheLock) {
            CachedViewerImages cached = ntkViewerImageUrlCache.get(key);
            if(cached == null || now - cached.cachedAt >= NTK_VIEWER_IMAGES_RECENT_CACHE_TRUST_MS)
                return Collections.emptyList();
            return new ArrayList<>(cached.urls);
        }
    }

    private void cacheNtkViewerImageUrls(String key, List<String> urls) {
        if(key == null || key.length() == 0 || urls == null || urls.isEmpty())
            return;
        synchronized (ntkViewerImageUrlCacheLock) {
            ntkViewerImageUrlCache.put(key, new CachedViewerImages(new ArrayList<>(urls), System.currentTimeMillis()));
        }
    }

    private void cancelNtkViewerImageWebViewRace(Context context, FutureTask<List<String>> webViewRace,
                                                String path, String reason) {
        if(webViewRace != null && !webViewRace.isDone())
            webViewRace.cancel(true);
        if(context == null)
            return;
        try {
            NtkWebViewFallbackManager.get(context).cancelActiveViewerImageFetchesForPath(path, reason);
        } catch (Exception ignored) {
        }
    }

    private void invalidateCachedNtkViewerImageUrls(String key) {
        if(key == null || key.length() == 0)
            return;
        synchronized (ntkViewerImageUrlCacheLock) {
            ntkViewerImageUrlCache.remove(key);
            ntkViewerImageUrlMissCache.remove(key);
        }
    }

    private boolean hasFreshNtkViewerImageUrlMiss(String key) {
        if(key == null || key.length() == 0)
            return false;
        long now = System.currentTimeMillis();
        synchronized (ntkViewerImageUrlCacheLock) {
            Long missedAt = ntkViewerImageUrlMissCache.get(key);
            if(missedAt == null)
                return false;
            if(now - missedAt >= NTK_VIEWER_IMAGE_URL_MISS_CACHE_TTL_MS) {
                ntkViewerImageUrlMissCache.remove(key);
                return false;
            }
            return true;
        }
    }

    private void cacheNtkViewerImageUrlMiss(String key) {
        if(key == null || key.length() == 0)
            return;
        synchronized (ntkViewerImageUrlCacheLock) {
            ntkViewerImageUrlMissCache.put(key, System.currentTimeMillis());
        }
    }

    private void cacheNtkViewerImageManifestMissing(String path) {
        String normalized = normalizeNtkViewerManifestMissingPath(path);
        if(normalized.length() == 0)
            return;
        synchronized (ntkViewerImageUrlCacheLock) {
            ntkViewerImageManifestMissingCache.put(normalized, System.currentTimeMillis());
        }
    }

    public boolean hasRecentNtkViewerImageManifestMissing(String path) {
        String normalized = normalizeNtkViewerManifestMissingPath(path);
        if(normalized.length() == 0)
            return false;
        long now = System.currentTimeMillis();
        synchronized (ntkViewerImageUrlCacheLock) {
            Long missedAt = ntkViewerImageManifestMissingCache.get(normalized);
            if(missedAt == null)
                return false;
            if(now - missedAt >= NTK_VIEWER_IMAGE_MANIFEST_MISSING_TTL_MS) {
                ntkViewerImageManifestMissingCache.remove(normalized);
                return false;
            }
            return true;
        }
    }

    private static String normalizeNtkViewerManifestMissingPath(String path) {
        if(path == null)
            return "";
        String normalized = path.trim();
        int hash = normalized.indexOf('#');
        if(hash >= 0)
            normalized = normalized.substring(0, hash);
        return normalized;
    }

    public static NtkCachedImageIdentity cachedNtkImageIdentity(String path) {
        String normalized = normalizeNtkImageIdentityPath(path);
        if(normalized.length() == 0)
            return null;
        Context appContext = MainApplication.appContext;
        if(appContext == null)
            return null;
        try {
            String raw = appContext.getSharedPreferences("mangaView", Context.MODE_PRIVATE)
                    .getString(NTK_IMAGE_IDENTITY_PREF_PREFIX + normalized, "");
            if(raw == null || raw.length() == 0)
                return null;
            JSONObject json = new JSONObject(raw);
            long cachedAt = json.optLong("cachedAt", 0L);
            if(cachedAt <= 0L || System.currentTimeMillis() - cachedAt >= NTK_IMAGE_IDENTITY_CACHE_TTL_MS)
                return null;
            String kind = json.optString("kind", "");
            String workId = json.optString("workId", "");
            String episodeId = json.optString("episodeId", "");
            int count = json.optInt("count", 0);
            if(!workId.matches("\\d{1,12}") || !episodeId.matches("\\d{1,12}"))
                return null;
            return new NtkCachedImageIdentity(normalized, kind, workId, episodeId, count, cachedAt);
        } catch(Exception ignored) {
            return null;
        }
    }

    public static void rememberCachedNtkImageIdentityFromUrls(String path, String kind,
                                                              List<String> urls, int count) {
        String normalized = normalizeNtkImageIdentityPath(path);
        Context appContext = MainApplication.appContext;
        if(appContext == null || normalized.length() == 0 || urls == null || urls.isEmpty())
            return;
        NtkCachedImageIdentity identity = ntkImageIdentityFromUrls(normalized, kind, urls, count);
        if(identity == null)
            return;
        try {
            JSONObject json = new JSONObject();
            json.put("kind", identity.kind);
            json.put("workId", identity.workId);
            json.put("episodeId", identity.episodeId);
            json.put("count", identity.count);
            json.put("cachedAt", identity.cachedAt);
            boolean stored = appContext.getSharedPreferences("mangaView", Context.MODE_PRIVATE).edit()
                    .putString(NTK_IMAGE_IDENTITY_PREF_PREFIX + normalized, json.toString())
                    .commit();
            Log.d(TAG, "ntk_image_identity_cached path=" + normalized
                    + ",kind=" + identity.kind
                    + ",workId=" + identity.workId
                    + ",episodeId=" + identity.episodeId
                    + ",count=" + identity.count
                    + ",stored=" + stored);
        } catch(Exception e) {
            Log.d(TAG, "ntk_image_identity_cache_error path=" + normalized + "," + e);
        }
    }

    public static void rememberCachedNtkImageIdentityFromApiBody(String path, String kind, String body) {
        if(body == null || body.length() == 0)
            return;
        try {
            JSONObject response = new JSONObject(body);
            JSONArray images = response.optJSONArray("images");
            if(images == null || images.length() == 0)
                return;
            ArrayList<String> rawUrls = new ArrayList<>();
            for(int i = 0; i < images.length(); i++) {
                JSONObject image = images.optJSONObject(i);
                if(image == null)
                    continue;
                String src = image.optString("src", "");
                if(src.length() > 0)
                    rawUrls.add(src);
                JSONArray candidates = image.optJSONArray("srcCandidates");
                if(candidates == null)
                    continue;
                for(int j = 0; j < candidates.length(); j++) {
                    String candidate = candidates.optString(j, "");
                    if(candidate.length() > 0)
                        rawUrls.add(candidate);
                }
            }
            rememberCachedNtkImageIdentityFromUrls(path, kind, rawUrls, images.length());
        } catch(Exception ignored) {
        }
    }

    private void rememberNtkImageIdentityFromUrls(String path, String kind, List<String> urls, int count) {
        String normalized = normalizeNtkImageIdentityPath(path);
        if(context == null || normalized.length() == 0 || urls == null || urls.isEmpty())
            return;
        rememberCachedNtkImageIdentityFromUrls(normalized, kind, urls, count);
    }

    private static NtkCachedImageIdentity ntkImageIdentityFromUrls(String path, String kind,
                                                                   List<String> urls, int count) {
        String expectedKind = kind == null ? "" : kind.trim().toLowerCase(Locale.ROOT);
        for(String url : urls) {
            NtkCachedImageIdentity identity = ntkImageIdentityFromUrl(path, expectedKind, url, count);
            if(identity != null)
                return identity;
        }
        return null;
    }

    private static NtkCachedImageIdentity ntkImageIdentityFromUrl(String path, String expectedKind,
                                                                  String url, int count) {
        if(url == null || url.length() == 0)
            return null;
        try {
            HttpUrl parsed = HttpUrl.parse(url.trim());
            if(parsed == null)
                return null;
            String imagePath = parsed.encodedPath() == null ? "" : parsed.encodedPath();
            String kind = "";
            String workId = "";
            String episodeId = "";
            Matcher matcher = Pattern.compile(
                    "^/(manhwa|webtoon)/(\\d{1,12})/(\\d{1,12})/(?:p)?\\d{1,5}\\.(?:jpg|jpeg|png|webp)$",
                    Pattern.CASE_INSENSITIVE).matcher(imagePath);
            if(matcher.find()) {
                kind = matcher.group(1).toLowerCase(Locale.ROOT);
                workId = matcher.group(2);
                episodeId = matcher.group(3);
            } else {
                matcher = Pattern.compile(
                        "^/(?:blacktoon|black)/episodes/(\\d{1,12})/(\\d{1,12})/(?:p)?\\d{1,5}\\.(?:jpg|jpeg|png|webp)$",
                        Pattern.CASE_INSENSITIVE).matcher(imagePath);
                if(matcher.find()) {
                    kind = "webtoon";
                    workId = matcher.group(1);
                    episodeId = matcher.group(2);
                } else {
                    matcher = Pattern.compile(
                            "^/wt/episodes/([^/?#]{1,120})/(\\d{1,12})/(?:p)?\\d{1,5}\\.(?:jpg|jpeg|png|webp)$",
                            Pattern.CASE_INSENSITIVE).matcher(imagePath);
                    if(matcher.find()) {
                        kind = "webtoon";
                        workId = matcher.group(1);
                        episodeId = matcher.group(2);
                    }
                }
            }
            if(workId.length() == 0 || episodeId.length() == 0)
                return null;
            if(expectedKind.length() > 0 && kind.length() > 0 && !expectedKind.equals(kind))
                return null;
            int safeCount = count > 0 ? Math.min(count, 10000) : 0;
            return new NtkCachedImageIdentity(path, kind, workId, episodeId, safeCount,
                    System.currentTimeMillis());
        } catch(Exception ignored) {
            return null;
        }
    }

    private static String normalizeNtkImageIdentityPath(String path) {
        if(path == null)
            return "";
        String normalized = path.trim();
        int query = normalized.indexOf('?');
        if(query >= 0)
            normalized = normalized.substring(0, query);
        int hash = normalized.indexOf('#');
        if(hash >= 0)
            normalized = normalized.substring(0, hash);
        return normalized.matches("^/(?:manhwa|webtoon)/[^/?#]+/[^/?#]+$") ? normalized : "";
    }

    private static boolean isStrictNtkEpisodePath(String path) {
        return normalizeNtkImageIdentityPath(path).length() > 0;
    }

