    private static final class FragmentingTlsOutputStream extends OutputStream {
        private final Socket socket;
        private final OutputStream delegate;
        private boolean firstTlsRecord = true;

        FragmentingTlsOutputStream(Socket socket, OutputStream delegate) {
            this.socket = socket;
            this.delegate = delegate;
        }

        @Override
        public void write(int b) throws IOException {
            firstTlsRecord = false;
            delegate.write(b);
        }

        @Override
        public void write(byte[] b, int off, int len) throws IOException {
            if(firstTlsRecord && looksLikeTlsClientHello(b, off, len)) {
                firstTlsRecord = false;
                fragmentClientHello(b, off, len);
                return;
            }
            if(len > 0)
                firstTlsRecord = false;
            delegate.write(b, off, len);
        }

        private void fragmentClientHello(byte[] b, int off, int len) throws IOException {
            try {
                socket.setTcpNoDelay(true);
            } catch (Exception ignored) {
            }
            if(fragmentClientHelloTlsRecords(b, off, len)) {
                return;
            }
            int first = Math.min(1, len);
            int second = Math.min(7, Math.max(0, len - first));
            int third = Math.min(64, Math.max(0, len - first - second));
            writeChunk(b, off, first);
            shortDelay();
            writeChunk(b, off + first, second);
            shortDelay();
            writeChunk(b, off + first + second, third);
            shortDelay();
            int written = first + second + third;
            if(written < len)
                delegate.write(b, off + written, len - written);
            delegate.flush();
            Log.d(TAG, "ntk_sni_tcp_fragmented bytes=" + len);
        }

        private boolean fragmentClientHelloTlsRecords(byte[] b, int off, int len) throws IOException {
            if(b == null || off < 0 || len < 6 || off + len > b.length)
                return false;
            int recordPayloadLen = ((b[off + 3] & 0xff) << 8) | (b[off + 4] & 0xff);
            int recordTotalLen = 5 + recordPayloadLen;
            if(recordPayloadLen <= 0 || recordTotalLen > len)
                return false;
            int payloadOffset = off + 5;
            int[] sniHostRange = tlsClientHelloSniHostRange(b, off, recordTotalLen);
            if(sniHostRange != null && sniHostRange[1] > sniHostRange[0]) {
                /*
                 * Carrier filters inspect the clear-text SNI inside ClientHello. Split exactly
                 * across that hostname instead of rewriting the complete 500+ byte handshake into
                 * four-byte records. Three flushed TLS records retain the required parser break
                 * while avoiding roughly a second of artificial sleeps on every cold connection.
                 */
                int middle = sniHostRange[0]
                        + Math.max(1, (sniHostRange[1] - sniHostRange[0]) / 2);
                middle = Math.min(middle, sniHostRange[1] - 1);
                writeTlsRecordChunk(b, off, payloadOffset, middle - payloadOffset);
                shortDelay();
                writeTlsRecordChunk(b, off, middle, 1);
                shortDelay();
                writeTlsRecordChunk(b, off, middle + 1,
                        off + recordTotalLen - middle - 1);
                if(recordTotalLen < len)
                    delegate.write(b, off + recordTotalLen, len - recordTotalLen);
                delegate.flush();
                Log.d(TAG, "ntk_sni_tls_record_fragmented bytes=" + len
                        + ",mode=sni-targeted,records=3");
                return true;
            }
            int payloadRemaining = recordPayloadLen;
            int payloadCursor = payloadOffset;
            while(payloadRemaining > 0) {
                int chunk = Math.min(4, payloadRemaining);
                writeTlsRecordChunk(b, off, payloadCursor, chunk);
                payloadCursor += chunk;
                payloadRemaining -= chunk;
                shortDelay();
            }
            if(recordTotalLen < len)
                delegate.write(b, off + recordTotalLen, len - recordTotalLen);
            delegate.flush();
            Log.d(TAG, "ntk_sni_tls_record_fragmented bytes=" + len
                    + ",mode=fine-grained-fallback");
            return true;
        }

        private void writeTlsRecordChunk(byte[] b, int recordOff, int payloadOff, int len) throws IOException {
            if(len <= 0)
                return;
            delegate.write(new byte[]{
                    b[recordOff],
                    b[recordOff + 1],
                    b[recordOff + 2],
                    (byte)((len >>> 8) & 0xff),
                    (byte)(len & 0xff)
            });
            delegate.write(b, payloadOff, len);
            delegate.flush();
        }

        private void writeChunk(byte[] b, int off, int len) throws IOException {
            if(len <= 0)
                return;
            delegate.write(b, off, len);
            delegate.flush();
        }

        private void shortDelay() throws IOException {
            try {
                Thread.sleep(2L);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                InterruptedIOException interrupted = new InterruptedIOException("Interrupted while fragmenting TLS ClientHello");
                interrupted.initCause(e);
                throw interrupted;
            }
        }

        @Override
        public void flush() throws IOException {
            delegate.flush();
        }

        @Override
        public void close() throws IOException {
            delegate.close();
        }
    }

    private static boolean looksLikeTlsClientHello(byte[] b, int off, int len) {
        if(b == null || len < 6 || off < 0 || off + len > b.length)
            return false;
        return (b[off] & 0xff) == 0x16
                && (b[off + 1] & 0xff) == 0x03
                && (b[off + 5] & 0xff) == 0x01;
    }

    private static int[] tlsClientHelloSniHostRange(byte[] bytes, int off, int len) {
        if(!looksLikeTlsClientHello(bytes, off, len))
            return null;
        int recordPayloadLength = readUnsignedShort(bytes, off + 3, off + len);
        int recordEnd = off + 5 + recordPayloadLength;
        if(recordPayloadLength < 4 || recordEnd > off + len)
            return null;
        int payload = off + 5;
        int handshakeLength = ((bytes[payload + 1] & 0xff) << 16)
                | ((bytes[payload + 2] & 0xff) << 8)
                | (bytes[payload + 3] & 0xff);
        int handshakeEnd = payload + 4 + handshakeLength;
        if(handshakeEnd > recordEnd)
            return null;
        int cursor = payload + 4;
        // legacy_version + random
        if(cursor + 34 > handshakeEnd)
            return null;
        cursor += 34;
        if(cursor >= handshakeEnd)
            return null;
        int sessionIdLength = bytes[cursor++] & 0xff;
        if(cursor + sessionIdLength + 2 > handshakeEnd)
            return null;
        cursor += sessionIdLength;
        int cipherSuitesLength = readUnsignedShort(bytes, cursor, handshakeEnd);
        if(cipherSuitesLength < 0 || cursor + 2 + cipherSuitesLength + 1 > handshakeEnd)
            return null;
        cursor += 2 + cipherSuitesLength;
        int compressionMethodsLength = bytes[cursor++] & 0xff;
        if(cursor + compressionMethodsLength + 2 > handshakeEnd)
            return null;
        cursor += compressionMethodsLength;
        int extensionsLength = readUnsignedShort(bytes, cursor, handshakeEnd);
        if(extensionsLength < 0 || cursor + 2 + extensionsLength > handshakeEnd)
            return null;
        cursor += 2;
        int extensionsEnd = cursor + extensionsLength;
        while(cursor + 4 <= extensionsEnd) {
            int extensionType = readUnsignedShort(bytes, cursor, extensionsEnd);
            int extensionLength = readUnsignedShort(bytes, cursor + 2, extensionsEnd);
            if(extensionType < 0 || extensionLength < 0
                    || cursor + 4 + extensionLength > extensionsEnd) {
                return null;
            }
            int extensionData = cursor + 4;
            int extensionEnd = extensionData + extensionLength;
            if(extensionType == 0 && extensionLength >= 5) {
                int listLength = readUnsignedShort(bytes, extensionData, extensionEnd);
                int entry = extensionData + 2;
                int listEnd = entry + listLength;
                if(listLength < 0 || listEnd > extensionEnd)
                    return null;
                while(entry + 3 <= listEnd) {
                    int nameType = bytes[entry++] & 0xff;
                    int nameLength = readUnsignedShort(bytes, entry, listEnd);
                    entry += 2;
                    if(nameLength <= 0 || entry + nameLength > listEnd)
                        return null;
                    if(nameType == 0)
                        return new int[]{entry, entry + nameLength};
                    entry += nameLength;
                }
                return null;
            }
            cursor = extensionEnd;
        }
        return null;
    }

    private static int readUnsignedShort(byte[] bytes, int offset, int limit) {
        if(bytes == null || offset < 0 || offset + 2 > limit || limit > bytes.length)
            return -1;
        return ((bytes[offset] & 0xff) << 8) | (bytes[offset + 1] & 0xff);
    }

    static String tlsClientHelloSniHostForTest(byte[] bytes) {
        int[] range = bytes == null ? null : tlsClientHelloSniHostRange(bytes, 0, bytes.length);
        if(range == null)
            return null;
        return new String(bytes, range[0], range[1] - range[0], StandardCharsets.US_ASCII);
    }

    public interface RequestWork<T> {
        T run() throws Exception;
    }

    public static class RequestGroup {
        private final Set<Call> calls = java.util.Collections.synchronizedSet(new java.util.HashSet<>());
        private final Set<RequestGroup> children = java.util.Collections.synchronizedSet(new java.util.HashSet<>());
        private volatile boolean cancelled = false;
        private volatile boolean wolfWebViewFallback = false;
        private volatile boolean priorityWebViewFallback = false;
        private volatile boolean userVisible = false;

        public RequestGroup allowWolfWebViewFallback() {
            wolfWebViewFallback = true;
            return this;
        }

        public boolean allowsWolfWebViewFallback() {
            return wolfWebViewFallback;
        }

        public RequestGroup prioritizeWebViewFallback() {
            wolfWebViewFallback = true;
            priorityWebViewFallback = true;
            return this;
        }

        public RequestGroup clearWebViewFallbackPriority() {
            priorityWebViewFallback = false;
            return this;
        }

        public boolean prioritizesWebViewFallback() {
            return priorityWebViewFallback;
        }

        public RequestGroup userVisible() {
            userVisible = true;
            return this;
        }

        public boolean isUserVisible() {
            return userVisible;
        }

        void add(Call call) {
            synchronized (calls) {
                if(cancelled) {
                    call.cancel();
                    return;
                }
                calls.add(call);
            }
        }

        void remove(Call call) {
            calls.remove(call);
        }

        RequestGroup child() {
            RequestGroup child = new RequestGroup();
            child.wolfWebViewFallback = wolfWebViewFallback;
            child.priorityWebViewFallback = priorityWebViewFallback;
            child.userVisible = userVisible;
            synchronized (children) {
                if(cancelled) {
                    child.cancel();
                } else {
                    children.add(child);
                }
            }
            return child;
        }

        void removeChild(RequestGroup child) {
            if(child != null)
                children.remove(child);
        }

        public boolean isCancelled() {
            return cancelled;
        }

        public void cancel() {
            cancelled = true;
            synchronized (calls) {
                for(Call call : calls)
                    call.cancel();
                calls.clear();
            }
            synchronized (children) {
                for(RequestGroup child : children)
                    child.cancel();
                children.clear();
            }
        }
    }


